[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-01)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with date"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-02)" = '' ] || { echo "list --room with another date should be empty"; fail=1; }
BOOKINGS=$t bash src/list.sh --room >/dev/null 2>&1; [ $? = 2 ] || { echo "--room without a value should exit 2"; fail=1; }
err=$(BOOKINGS=$t bash src/list.sh --room 2>&1 >/dev/null); [ "$err" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "--room without a value should print usage"; fail=1; }
BOOKINGS=$t bash src/list.sh --room aoi 2026/01/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "--room with a malformed date should exit 2"; fail=1; }
rm -f "$t"; exit $fail

