t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
rm -f "$t"
t2=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\naoi\t2026-01-02\t09:00\t10:00\tz\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t2"
[ "$(BOOKINGS=$t2 bash src/list.sh --room aoi 2026-01-01)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with a date"; fail=1; }
[ -z "$(BOOKINGS=$t2 bash src/list.sh --room kaede 2026-01-02)" ] || { echo "list --room with a date should filter both"; fail=1; }
rm -f "$t2"
e=$(mktemp); BOOKINGS=/dev/null bash src/list.sh --room >/dev/null 2>"$e"; [ $? = 2 ] || { echo "list --room without a value should exit 2"; fail=1; }
grep -qx 'usage: list.sh \[--room ROOM\] \[DATE\]' "$e" || { echo "list --room without a value should print usage"; fail=1; }
rm -f "$e"; exit $fail
EOF
bash spec/list_room.spec.sh && echo SPEC-OK; bash tools/check 2>&1 | tail -3; echo "== lint"; bash tools/lint 2>&1 | tail -5; echo "lint-exit=$?"

